(function(root){'use strict';
const normalize=value=>String(value).toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,' ').trim();
function search(catalog,query){const tokens=normalize(query).split(' ').filter(Boolean);return catalog.products.filter(p=>{const hay=normalize([p.title,...p.aliases,p.family,p.material||'',(p.material||'').replace(/cotton/gi,'pamuk').replace(/paper/gi,'kağıt'),catalog.categories.find(cat=>cat.id===p.category)?.label||'',p.fulfillmentProvider||'',catalog.providers.find(v=>v.id===p.providerId)?.name||''].join(' '));return tokens.every(t=>hay.includes(t));});}
function quote(p,country){const shipping=p.shipping?.[country];return {...p,shippingMinor:Number.isInteger(shipping)?shipping:null,totalMinor:Number.isInteger(shipping)&&Number.isInteger(p.baseMinor)?p.baseMinor+shipping:null};}
function sort(rows,mode){return [...rows].sort((a,b)=>{const key=mode==='total'?'totalMinor':mode==='delivery'?'deliveryDays':'baseMinor',x=a[key],y=b[key];if(x==null&&y==null)return a.title.localeCompare(b.title);if(x==null)return 1;if(y==null)return -1;return x-y;});}
function offers(catalog,f={}){return search(catalog,f.query||'').filter(p=>(!f.category||(f.category.startsWith('etsy-')?POD_TAXONOMY_ENGINE.isWithin(POD_TAXONOMY_ENGINE.classify(p),f.category):p.category===f.category))&&(!f.provider||p.providerId===f.provider)&&(!f.material||normalize((p.material||'').replace(/cotton/gi,'pamuk').replace(/paper/gi,'kağıt')).includes(f.material))&&(f.maxPrice==null||p.baseMinor/100<=f.maxPrice)).sort((a,b)=>f.sort==='high'?b.baseMinor-a.baseMinor:a.baseMinor-b.baseMinor);}
function groups(catalog,f={}){const rows=offers(catalog,f);const map=new Map();for(const p of rows){if(!map.has(p.family))map.set(p.family,[]);map.get(p.family).push(p);}return [...map].map(([family,offers])=>({family,offers,minPrice:Math.min(...offers.map(p=>p.baseMinor)),providerCount:new Set(offers.map(p=>p.providerId+'|'+(p.fulfillmentProvider||''))).size})).sort((a,b)=>f.sort==='high'?b.minPrice-a.minPrice:f.sort==='providers'?b.providerCount-a.providerCount:a.minPrice-b.minPrice);}
root.POD_ENGINE={normalize,search,quote,sort,groups,offers};})(globalThis);
